		key, _, ok := strings.Cut(e, "=")
		if !ok {
			continue
		}
		if strings.HasPrefix(key, "GIT_CONFIG_") {
			t.Setenv(key, "")
		}
	}

	t.Setenv("GIT_CONFIG_GLOBAL", emptyConfigPath())
	t.Setenv("GIT_CONFIG_SYSTEM", emptyConfigPath())
	t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
	t.Setenv("GIT_CONFIG_COUNT", "0")
}

